	for(char i='A'; i<='Z'; ++i)
		if(vis[i]) dfs1(1,i,0,0);
	mat[0][0]=1; mat=mat*qpow(Q,n);
	dfs2(1,0); printf("%d\n",ans);
	return 0;
}
